sp_widget.client_script:
api.controller = function () {
    /* widget controller */
    var c = this;
};

sp_widget.css:
.ibar-kpi-card {
  text-align: center;
  padding: 16px 8px;
  border-radius: 4px;
  border: 1px solid $border-tertiary;
  margin-bottom: 16px;
  background: $background-primary;
}
.ibar-kpi-value {
  font-size: 28px;
  font-weight: 700;
  color: $text-color;
  line-height: 1.2;
}
.ibar-kpi-label {
  font-size: 11px;
  color: $text-muted;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-top: 4px;
}
.ibar-kpi-info { border-left: 3px solid $brand-info; }
.ibar-kpi-primary { border-left: 3px solid $brand-primary; }
.ibar-kpi-success { border-left: 3px solid $brand-success; }
.ibar-kpi-warning { border-left: 3px solid $brand-warning; }
.ibar-kpi-danger { border-left: 3px solid $brand-danger; }

sp_widget.script:
(function() {
  data.kpis = {
    total_applications: 0,
    pending_review: 0,
    in_progress: 0,
    build_ready: 0,
    completed: 0,
    clarification_pending: 0
  };

  try {
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    appGr.addQuery("active", true);
    appGr.setLimit(500);
    appGr.query();

    while (appGr.next()) {
      data.kpis.total_applications++;
      var status = appGr.getValue("questionnaire_status");

      switch (status) {
        case "submitted":
        case "admin_review":
          data.kpis.pending_review++;
          break;
        case "in_progress":
        case "draft":
          data.kpis.in_progress++;
          break;
        case "build_ready":
          data.kpis.build_ready++;
          break;
        case "completed":
          data.kpis.completed++;
          break;
        case "clarification_requested":
          data.kpis.clarification_pending++;
          break;
      }
    }
  } catch (e) {
    gs.error("IBAR Admin KPI Summary widget error: " + e.message);
  }
})();
